import json,numpy as np
from pathlib import Path
b=Path(__file__).parent;m=json.load(open(b/'125690413/measurements.json'));e=[x for x in m['events'] if x.get('timing_usable') and x['sector']!=41];n=np.array([x['cycle'] for x in e]);t=np.array([x['mid_btjd'] for x in e]);er=np.array([x['timing_error_days'] for x in e]);X=np.array([np.ones(len(n)),n-n.min()]).T;c=np.linalg.inv((X/er[:,None]).T@(X/er[:,None]));v=c@((X/er[:,None]).T@(t/er));out={'selection':'Sensitivity only: remove whole structured-baseline sector41, retain sectors15/55; adopted report retains all18 measured events and chi-square inflation.','event_count':len(e),'period_days':v[1],'full_period_days':m['period_days'],'difference_days':v[1]-m['period_days']};json.dump(out,open(b/'125690413/timing-sensitivity.json','w'),indent=2);print(out)
